const body = ($('Webhook').first().json.body) || {};
const ai = body.ai || {};
const context = body.context || {};
const transcript = String(body.transcript || '').trim();
if (!transcript) throw new Error('transcript_required');
const provider = String(ai.provider || 'gemini').toLowerCase() === 'openai' ? 'openai' : 'gemini';
const baseUrl = provider === 'openai' ? 'https://api.openai.com/v1' : 'https://generativelanguage.googleapis.com/v1beta/openai';
const model = String(ai.model || (provider === 'openai' ? 'gpt-4.1-mini' : 'gemini-2.5-flash')).trim();
const temperature = Math.max(0, Math.min(1, Number(ai.temperature) || 0.2));
const policy = String(ai.systemPrompt || '').trim();
const system = policy + '\n\nCONTEXTO AUTORITATIVO DO ATENDIMENTO:\n' + JSON.stringify(context) + '\n\nREGRAS DE SAIDA: devolva somente JSON valido, sem markdown. Nao invente nomes, produtos ou fatos. Corrija erros foneticos apenas quando o contexto sustentar. O campo summary deve ser um resumo executivo curto em pt-BR. O campo report deve seguir: {customerIntent:string,needs:string[],products:string[],objections:string[],commitments:string[],nextSteps:string[],opportunities:string[],alerts:string[],sentiment:string,confidence:number}. confidence fica entre 0 e 1.';
const messages = [{ role: 'system', content: system }, { role: 'user', content: 'Transcricao integral do atendimento:\n' + transcript }];
const requestBody = { model, messages, response_format: { type: 'json_object' } };
if (!(provider === 'openai' && /^gpt-5(?:-|$)/i.test(model))) requestBody.temperature = temperature;
return [{ json: { baseUrl, apiKey: String(ai.apiKey || ''), requestBody } }];

let response = $input.first().json || {};
if (Array.isArray(response)) response = response[0] || {};
const content = String((((response.choices || [])[0] || {}).message || {}).content || '').trim();
if (!content) throw new Error('empty_ai_response');
let text = content;
const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fence) text = fence[1].trim();
const start = text.indexOf('{'); const end = text.lastIndexOf('}');
if (start >= 0 && end > start) text = text.slice(start, end + 1);
const parsed = JSON.parse(text);
const summary = String(parsed.summary || '').trim();
if (!summary) throw new Error('summary_required');
const source = parsed.report && typeof parsed.report === 'object' ? parsed.report : {};
const list = (value) => Array.isArray(value) ? value.map((item) => String(item || '').trim()).filter(Boolean).slice(0, 30) : [];
const confidence = Math.max(0, Math.min(1, Number(source.confidence) || 0));
const report = { customerIntent: String(source.customerIntent || '').trim(), needs: list(source.needs), products: list(source.products), objections: list(source.objections), commitments: list(source.commitments), nextSteps: list(source.nextSteps), opportunities: list(source.opportunities), alerts: list(source.alerts), sentiment: String(source.sentiment || '').trim(), confidence };
return [{ json: { summary: summary.slice(0, 20000), report } }];
